    """Fill the convex hull of the non-background markers with color 3."""
    h, w = len(grid), len(grid[0])
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != grid[0][0]]
    if not markers:
        return [row[:] for row in grid]

    def cross(o, a, b):
        return (a[1] - o[1]) * (b[0] - o[0]) - (a[0] - o[0]) * (b[1] - o[1])

    pts = sorted(set(markers))
    if len(pts) <= 2:
        hull = pts
    else:
        lower = []
        for p in pts:
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                lower.pop()
            lower.append(p)
        upper = []
        for p in reversed(pts):
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                upper.pop()
            upper.append(p)
        hull = lower[:-1] + upper[:-1]

    def inside(r, c):
        if len(hull) == 1:
            return (r, c) == hull[0]
        if len(hull) == 2:
            a, b = hull
            return cross(a, b, (r, c)) == 0 and min(a[0], b[0]) <= r <= max(a[0], b[0]) and min(a[1], b[1]) <= c <= max(a[1], b[1])
        signs = []
        p = (r, c)
        for i, a in enumerate(hull):
            v = cross(a, hull[(i + 1) % len(hull)], p)
            if v:
                signs.append(v > 0)
        return not signs or all(s == signs[0] for s in signs)

    out = [row[:] for row in grid]
    bg = grid[0][0]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and inside(r, c):
                out[r][c] = 3
    return out
